def norm(s):
    return re.sub(r"\s+", " ", s).strip()


def main(append):
    bad = 0
    rows = []
    for r in ROWS:
        cid, sid, passage, lines = r[0], r[1], r[2], r[3]
        a, _, b = lines.partition("-")
        a, b = int(a), int(b or a)
        t = open(os.path.join(STUDY, "data", L, "text", FILE[sid] + ".txt"), encoding="utf-8").read().split("\n")
        if norm(passage) not in norm(" ".join(t[a - 1:b])):
            print("NOT FOUND", cid, sid, lines)
            bad += 1
        if "withheld" in passage:
            print("WITHHELD MARKER", cid)
            bad += 1
        rows.append({"claim_id": "LH055-" + cid, "source_id": sid, "passage": passage,
                     "passage_locator": "%s/text/%s.txt lines %s" % (L, FILE[sid], lines),
                     "campaign": r[4], "event_window": r[5], "publication_date": PUB[sid], "observed_at": OBS[sid],
                     "basis": r[6], "topic": r[7], "evidence_origin": r[8], "statement": r[9], "value": r[10],
                     "unit": r[11], "outcome": r[12], "limitation": r[13]})
    print(len(rows), "rows;", bad, "problems")
    if append and not bad:
        p = os.path.join(STUDY, "claims.csv")
        have = {c["claim_id"] for c in csv.DictReader(open(p))}
        assert not have & {r["claim_id"] for r in rows}, "ids already present"
        fields = next(csv.reader(open(p)))
        w = csv.DictWriter(open(p, "a", newline=""), fieldnames=fields, lineterminator="\n")
        for r in rows:
            w.writerow(r)
        print("appended")


if __name__ == "__main__":
    main("--append" in sys.argv)
